// Turns the Żubek pose SVGs (public/mascot/zubek-*.svg, generated by
// design/mascot/build-zubek.py) into src/components/mascot/zubek-svgs.ts so the
// Zubek component can inline them and GSAP can move the rig parts.
//
// Strips element ids (several poses can share a page; parts are found by
// data-part instead) and the root role/aria-label (the wrapper owns a11y).
//
// Run after regenerating the art:  node scripts/build-zubek-inline.mjs
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const SRC = 'public/mascot';
const OUT = 'src/components/mascot/zubek-svgs.ts';

const files = readdirSync(SRC).filter((f) => /^zubek-[a-z]+\.svg$/.test(f)).sort();
const entries = files.map((f) => {
  const pose = f.replace(/^zubek-|\.svg$/g, '');
  const svg = readFileSync(join(SRC, f), 'utf8')
    .replace(/\s+id="[^"]*"/g, '')
    .replace(/\s+role="img"/, '')
    .replace(/\s+aria-label="[^"]*"/, ' aria-hidden="true" focusable="false"')
    .replace(/>\s+</g, '><')
    .trim();
  return [pose, svg];
});

const body = `// GENERATED by scripts/build-zubek-inline.mjs from public/mascot/zubek-*.svg. Do not edit.
export const ZUBEK_SVG = {
${entries.map(([pose, svg]) => `  ${pose}: ${JSON.stringify(svg)},`).join('\n')}
} as const;

export type ZubekPose = keyof typeof ZUBEK_SVG;
`;
writeFileSync(OUT, body);
console.log(`wrote ${OUT}: ${entries.length} poses, ${(body.length / 1024).toFixed(1)} KB`);
